() => {
  const children = ['Code', 'Pull requests', 'Actions', 'Projects', 'Wiki']
  return (
    <UnderlineNav aria-label="Repository">
      {children.map((child: string, index: number) => (
        <UnderlineNavItem
          key={index}
          href="#"
          aria-current={index === 0 ? 'page' : undefined}
        >
          {child}
        </UnderlineNavItem>
      ))}
    </UnderlineNav>
  )
}

() => {
  return (
    <UnderlineNav aria-label="Repository with counters">
      <UnderlineNav.Item
        aria-current="page"
        leadingVisual={<CodeIcon />}
        counter="11K"
      >
        Code
      </UnderlineNav.Item>
      <UnderlineNav.Item leadingVisual={<IssueOpenedIcon />} counter={12}>
        Issues
      </UnderlineNav.Item>
    </UnderlineNav>
  )
}

({ initialSelectedIndex = 1 }: { initialSelectedIndex?: number }) => {
  const [selectedIndex, setSelectedIndex] = React.useState<number | null>(
    initialSelectedIndex,
  )
  return (
    <UnderlineNav aria-label="Repository" hideIconsBreakpoint="medium">
      {items.map((item, index) => (
        <UnderlineNav.Item
          key={item.navigation}
          leadingVisual={item.icon}
          aria-current={index === selectedIndex ? 'page' : undefined}
          // Set so that navigation in interaction tests does not cause the
          // page to load the storybook iframe URL and instead keeps the test in
          // the local preview
          target="_self"
          onSelect={(event) => {
            event.preventDefault()
            setSelectedIndex(index)
          }}
          counter={item.counter}
          href={item.href}
        >
          {item.navigation}
        </UnderlineNav.Item>
      ))}
    </UnderlineNav>
  )
}

() => {
  const [selectedIndex, setSelectedIndex] = React.useState<number | null>(1)
  return (
    <UnderlineNav
      aria-label="Repository with loading counters"
      loadingCounters={true}
    >
      {items.map((item, index) => (
        <UnderlineNav.Item
          key={item.navigation}
          leadingVisual={item.icon}
          aria-current={index === selectedIndex ? 'page' : undefined}
          onSelect={() => setSelectedIndex(index)}
          counter={item.counter}
        >
          {item.navigation}
        </UnderlineNav.Item>
      ))}
    </UnderlineNav>
  )
}
